{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2180-01-31 19:15:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee. I’ll be your doctor during this stay. You came in with nausea and vomiting again—can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2180-01-31 19:16:30",
      "speaker": "Patient",
      "text": "Yes, I woke up this morning feeling nauseous and vomited just spit—no food, nothing. I haven’t eaten anything today. It’s been like this for a few days now."
    },
    {
      "turn_number": 3,
      "time": "2180-01-31 19:17:45",
      "speaker": "Doctor",
      "text": "I see. Any pain in your belly when you vomit?"
    },
    {
      "turn_number": 4,
      "time": "2180-01-31 19:18:10",
      "speaker": "Patient",
      "text": "Just a general ache, nothing sharp. No diarrhea or blood in stool."
    },
    {
      "turn_number": 5,
      "time": "2180-01-31 19:19:00",
      "speaker": "Doctor",
      "text": "Okay. And you mentioned back pain too?"
    },
    {
      "turn_number": 6,
      "time": "2180-01-31 19:19:30",
      "speaker": "Patient",
      "text": "Yes, it’s usually there, but today it’s worse—especially when I move. It’s a nagging pain, maybe a 6 out of 10."
    },
    {
      "turn_number": 7,
      "time": "2180-01-31 19:20:15",
      "speaker": "Doctor",
      "text": "No numbness, tingling, or trouble with bladder or bowels?"
    },
    {
      "turn_number": 8,
      "time": "2180-01-31 19:20:40",
      "speaker": "Patient",
      "text": "No, none of that."
    },
    {
      "turn_number": 9,
      "time": "2180-01-31 19:21:00",
      "speaker": "Doctor",
      "text": "We’ll get some labs and imaging. Your white blood cell count is high—17.4—so we’re checking for infection, but your chest X-ray looks clear."
    },
    {
      "turn_number": 10,
      "time": "2180-01-31 19:22:00",
      "speaker": "Patient",
      "text": "Is that from the vomiting?"
    },
    {
      "turn_number": 11,
      "time": "2180-01-31 19:22:30",
      "speaker": "Doctor",
      "text": "Not usually. We’ll keep an eye on it. We also did a spine X-ray because of your back pain."
    },
    {
      "turn_number": 12,
      "time": "2180-01-31 19:23:15",
      "speaker": "Patient",
      "text": "Oh, okay. I’ve had back issues before, but it’s never this bad."
    },
    {
      "turn_number": 13,
      "time": "2180-01-31 21:10:00",
      "speaker": "Doctor",
      "text": "We got the T-spine film back. There’s a new compression fracture in two of your mid-back bones. That’s likely why the pain is worse."
    },
    {
      "turn_number": 14,
      "time": "2180-01-31 21:11:30",
      "speaker": "Patient",
      "text": "A fracture? But I didn’t fall or anything!"
    },
    {
      "turn_number": 15,
      "time": "2180-01-31 21:12:15",
      "speaker": "Doctor",
      "text": "With chronic conditions like yours and possible osteoporosis, bones can weaken. Sometimes even normal movement can cause a fracture."
    },
    {
      "turn_number": 16,
      "time": "2180-01-31 21:13:00",
      "speaker": "Patient",
      "text": "That’s scary. Is it serious?"
    },
    {
      "turn_number": 17,
      "time": "2180-01-31 21:13:45",
      "speaker": "Doctor",
      "text": "It’s not an emergency, but it needs attention. We’ll manage the pain and make sure you follow up with your primary doctor about bone health."
    },
    {
      "turn_number": 18,
      "time": "2180-01-31 21:14:30",
      "speaker": "Patient",
      "text": "Okay, thank you."
    },
    {
      "turn_number": 19,
      "time": "2180-02-01 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your blood cultures came back—no infection. The high white count is likely from stress or inflammation, not an active infection."
    },
    {
      "turn_number": 20,
      "time": "2180-02-01 08:01:15",
      "speaker": "Patient",
      "text": "So no antibiotics?"
    },
    {
      "turn_number": 21,
      "time": "2180-02-01 08:02:00",
      "speaker": "Doctor",
      "text": "Not needed. We’re focusing on your gastroparesis and nutrition. You’ve lost 50 pounds in a year—that’s a big concern."
    },
    {
      "turn_number": 22,
      "time": "2180-02-01 08:03:00",
      "speaker": "Patient",
      "text": "I just can’t keep food down. I’ve tried everything—meds, Botox, small meals."
    },
    {
      "turn_number": 23,
      "time": "2180-02-01 08:04:15",
      "speaker": "Doctor",
      "text": "We’re talking with your gastroenterologist. They want a J-tube, but surgery wants to try a temporary feeding tube first—goes past the stomach into the small intestine."
    },
    {
      "turn_number": 24,
      "time": "2180-02-01 08:05:30",
      "speaker": "Patient",
      "text": "A tube in my nose again? I hate that."
    },
    {
      "turn_number": 25,
      "time": "2180-02-01 08:06:15",
      "speaker": "Doctor",
      "text": "It’s temporary. Helps us see if feeding past the stomach works before doing surgery."
    },
    {
      "turn_number": 26,
      "time": "2180-02-01 08:07:00",
      "speaker": "Patient",
      "text": "Alright, if it helps."
    },
    {
      "turn_number": 27,
      "time": "2180-02-02 09:30:00",
      "speaker": "Doctor",
      "text": "The Dobhoff tube is in—placed past your stomach. We’ll start slow feeding today."
    },
    {
      "turn_number": 28,
      "time": "2180-02-02 09:31:15",
      "speaker": "Patient",
      "text": "Already? How will I feel?"
    },
    {
      "turn_number": 29,
      "time": "2180-02-02 09:32:00",
      "speaker": "Doctor",
      "text": "Most people don’t feel it much. We’ll watch for nausea. If you tolerate it, this could be a step toward better nutrition."
    },
    {
      "turn_number": 30,
      "time": "2180-02-03 10:00:00",
      "speaker": "Doctor",
      "text": "Great news—you’ve had the feeding tube for two days, no nausea or vomiting. Your labs are improving."
    },
    {
      "turn_number": 31,
      "time": "2180-02-03 10:01:15",
      "speaker": "Patient",
      "text": "Really? I didn’t even notice it after the first day."
    },
    {
      "turn_number": 32,
      "time": "2180-02-03 10:02:00",
      "speaker": "Doctor",
      "text": "That’s a good sign. It means your body can handle nutrition past the stomach."
    },
    {
      "turn_number": 33,
      "time": "2180-02-04 14:00:00",
      "speaker": "Patient",
      "text": "Doctor, I pulled the tube out."
    },
    {
      "turn_number": 34,
      "time": "2180-02-04 14:01:00",
      "speaker": "Doctor",
      "text": "You did? Are you feeling okay? Any nausea?"
    },
    {
      "turn_number": 35,
      "time": "2180-02-04 14:02:00",
      "speaker": "Patient",
      "text": "No, I feel fine. I just want to go home. I’m tired of being here."
    },
    {
      "turn_number": 36,
      "time": "2180-02-04 14:03:15",
      "speaker": "Doctor",
      "text": "I understand. But we need to plan next steps. The tube worked well—your team may still recommend a permanent J-tube."
    },
    {
      "turn_number": 37,
      "time": "2180-02-04 14:04:00",
      "speaker": "Patient",
      "text": "I’ll think about it. Can I go home now?"
    },
    {
      "turn_number": 38,
      "time": "2180-02-04 14:05:00",
      "speaker": "Doctor",
      "text": "We’ll work on discharge. But please follow up with your GI and surgeon to discuss options."
    },
    {
      "turn_number": 39,
      "time": "2180-02-05 09:00:00",
      "speaker": "Doctor",
      "text": "Your potassium was low when you came in—2.6. That can make you weak and affect your heart."
    },
    {
      "turn_number": 40,
      "time": "2180-02-05 09:01:00",
      "speaker": "Patient",
      "text": "Is it better now?"
    },
    {
      "turn_number": 41,
      "time": "2180-02-05 09:01:45",
      "speaker": "Doctor",
      "text": "Yes, it’s 4.1 now. We’ll send you home with potassium pills—one daily, especially if you vomit again."
    },
    {
      "turn_number": 42,
      "time": "2180-02-05 09:02:30",
      "speaker": "Patient",
      "text": "Okay, I’ll take them."
    },
    {
      "turn_number": 43,
      "time": "2180-02-06 10:00:00",
      "speaker": "Doctor",
      "text": "Your blood pressure has been high—up to 170/99. We started you on metoprolol. Stress and pain can raise it."
    },
    {
      "turn_number": 44,
      "time": "2180-02-06 10:01:15",
      "speaker": "Patient",
      "text": "I’ve been anxious. Is it dangerous?"
    },
    {
      "turn_number": 45,
      "time": "2180-02-06 10:02:00",
      "speaker": "Doctor",
      "text": "Not acutely, but long-term it’s important to control. Keep taking the medication and monitor at home."
    },
    {
      "turn_number": 46,
      "time": "2180-02-06 10:03:00",
      "speaker": "Patient",
      "text": "Will I need it forever?"
    },
    {
      "turn_number": 47,
      "time": "2180-02-06 10:04:00",
      "speaker": "Doctor",
      "text": "Possibly. Your PCP can reassess once things settle."
    },
    {
      "turn_number": 48,
      "time": "2180-02-07 08:00:00",
      "speaker": "Doctor",
      "text": "We’re planning to discharge you tomorrow. Your nausea is controlled, labs are stable, and you’re walking fine."
    },
    {
      "turn_number": 49,
      "time": "2180-02-07 08:01:15",
      "speaker": "Patient",
      "text": "That’s good. What about the back pain?"
    },
    {
      "turn_number": 50,
      "time": "2180-02-07 08:02:00",
      "speaker": "Doctor",
      "text": "We’ve been using ketorolac and Valium as needed. You’ll go home with naproxen—a similar medicine—for one week."
    },
    {
      "turn_number": 51,
      "time": "2180-02-07 08:03:00",
      "speaker": "Patient",
      "text": "And the fracture?"
    },
    {
      "turn_number": 52,
      "time": "2180-02-07 08:04:15",
      "speaker": "Doctor",
      "text": "Follow up with your primary doctor about osteoporosis. They may start treatment to strengthen your bones."
    },
    {
      "turn_number": 53,
      "time": "2180-02-07 08:05:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 54,
      "time": "2180-02-08 09:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day. You’re being discharged home."
    },
    {
      "turn_number": 55,
      "time": "2180-02-08 09:01:00",
      "speaker": "Patient",
      "text": "Great. What meds am I taking now?"
    },
    {
      "turn_number": 56,
      "time": "2180-02-08 09:02:00",
      "speaker": "Doctor",
      "text": "Same ones: citalopram, levothyroxine, omeprazole. New ones: Zofran and Compazine for nausea if it returns, potassium daily, and naproxen for back pain."
    },
    {
      "turn_number": 57,
      "time": "2180-02-08 09:03:15",
      "speaker": "Patient",
      "text": "And the feeding tube decision?"
    },
    {
      "turn_number": 58,
      "time": "2180-02-08 09:04:00",
      "speaker": "Doctor",
      "text": "Still important to discuss with GI and surgery. The temporary tube worked, so a permanent one might help long-term."
    },
    {
      "turn_number": 59,
      "time": "2180-02-08 09:05:00",
      "speaker": "Patient",
      "text": "I’ll make the appointment."
    },
    {
      "turn_number": 60,
      "time": "2180-02-08 09:06:00",
      "speaker": "Doctor",
      "text": "Also, get your labs done next week—Chem 10—and fax the results to your doctor."
    },
    {
      "turn_number": 61,
      "time": "2180-02-08 09:07:00",
      "speaker": "Patient",
      "text": "Got it. Thank you for everything."
    },
    {
      "turn_number": 62,
      "time": "2180-02-08 09:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and don’t hesitate to call if nausea returns or pain worsens."
    },
    {
      "turn_number": 63,
      "time": "2180-02-08 09:09:00",
      "speaker": "Patient",
      "text": "I will. See you soon, I hope not!"
    },
    {
      "turn_number": 64,
      "time": "2180-02-08 09:10:00",
      "speaker": "Doctor",
      "text": "Hopefully not! But we’re here if you need us."
    },
    {
      "turn_number": 65,
      "time": "2180-02-08 09:11:00",
      "speaker": "Patient",
      "text": "One more thing—should I avoid lifting?"
    },
    {
      "turn_number": 66,
      "time": "2180-02-08 09:12:00",
      "speaker": "Doctor",
      "text": "Yes, especially with the spine fracture. No heavy lifting for several weeks. Use caution with movement."
    },
    {
      "turn_number": 67,
      "time": "2180-02-08 09:13:00",
      "speaker": "Patient",
      "text": "Understood."
    },
    {
      "turn_number": 68,
      "time": "2180-02-08 09:14:00",
      "speaker": "Doctor",
      "text": "And keep using the lidocaine patch for back pain if it helps."
    },
    {
      "turn_number": 69,
      "time": "2180-02-08 09:15:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 70,
      "time": "2180-02-08 09:16:00",
      "speaker": "Doctor",
      "text": "Alright, the discharge papers are ready. You’re free to go when you’re set."
    },
    {
      "turn_number": 71,
      "time": "2180-02-08 09:17:00",
      "speaker": "Patient",
      "text": "Thank you again, Dr. Lee."
    },
    {
      "turn_number": 72,
      "time": "2180-02-08 09:18:00",
      "speaker": "Doctor",
      "text": "Take care. Stay hydrated, eat small meals, and follow up soon."
    },
    {
      "turn_number": 73,
      "time": "2180-02-08 09:19:00",
      "speaker": "Patient",
      "text": "I will. Bye!"
    },
    {
      "turn_number": 74,
      "time": "2180-02-08 09:20:00",
      "speaker": "Doctor",
      "text": "Goodbye!"
    },
    {
      "turn_number": 75,
      "time": "2180-02-08 09:21:00",
      "speaker": "Patient",
      "text": "Oh, one last question—can I drive?"
    },
    {
      "turn_number": 76,
      "time": "2180-02-08 09:22:00",
      "speaker": "Doctor",
      "text": "If you’re not on strong pain meds and feel alert, yes. But listen to your body."
    },
    {
      "turn_number": 77,
      "time": "2180-02-08 09:23:00",
      "speaker": "Patient",
      "text": "I’m off the IV meds, so I think I’m okay."
    },
    {
      "turn_number": 78,
      "time": "2180-02-08 09:24:00",
      "speaker": "Doctor",
      "text": "Then yes, you can drive. Just take it easy."
    },
    {
      "turn_number": 79,
      "time": "2180-02-08 09:25:00",
      "speaker": "Patient",
      "text": "Will do. Thanks again!"
    },
    {
      "turn_number": 80,
      "time": "2180-02-08 09:26:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Have a safe trip home."
    },
    {
      "turn_number": 81,
      "time": "2180-02-08 09:27:00",
      "speaker": "Patient",
      "text": "I will!"
    },
    {
      "turn_number": 82,
      "time": "2180-02-08 09:28:00",
      "speaker": "Doctor",
      "text": "Take care of yourself."
    },
    {
      "turn_number": 83,
      "time": "2180-02-08 09:29:00",
      "speaker": "Patient",
      "text": "I will. See you!"
    },
    {
      "turn_number": 84,
      "time": "2180-02-08 09:30:00",
      "speaker": "Doctor",
      "text": "Goodbye!"
    },
    {
      "turn_number": 85,
      "time": "2180-02-08 09:31:00",
      "speaker": "Patient",
      "text": "Bye!"
    }
  ],
  "summary": {
    "admission_start": "2180-01-31 19:03:00",
    "admission_end": "2180-02-08 14:36:00",
    "summary_paragraph": "A 55-year-old woman was admitted for recurrent nausea and vomiting, with a history of chronic gastroparesis, recent paraduodenal hernia repair, and multiple prior hospitalizations for similar symptoms. She presented with inability to tolerate oral intake, generalized abdominal pain with vomiting, and new-onset worsening back pain. Initial evaluation revealed leukocytosis, hypokalemia, and a non-obstructive bowel pattern. Imaging identified a new compression fracture in two mid-thoracic vertebrae. A post-pyloric Dobhoff tube was placed and enteral feeding initiated, which she tolerated well for two days before self-removing the tube and expressing readiness for discharge. Her nausea resolved, electrolytes normalized, and pain was controlled with medications. She was discharged home with improved symptoms, new prescriptions for antiemetics, potassium supplementation, and naproxen for back pain, and instructions to follow up with her gastroenterologist and primary care provider regarding long-term feeding options and osteoporosis management.",
    "problems": [
      "Gastroparesis",
      "Pathologic fracture of vertebrae",
      "Unspecified protein-calorie malnutrition",
      "Hypopotassemia",
      "Leukocytosis, unspecified",
      "Nausea with vomiting",
      "Osteoporosis, unspecified",
      "Esophageal reflux",
      "Unspecified essential hypertension",
      "Unspecified acquired hypothyroidism",
      "Dysthymic disorder",
      "Backache, unspecified"
    ]
  }
}
